//! Job API route handlers
//!
//! Provides endpoints for:
//! - POST /api/v1/load - Create and execute load jobs (sync or async)
//! - GET /api/v1/jobs/:id - Get job status and details

#![cfg(feature = "db")]

use axum::extract::{Path, Query, State};
use axum::http::StatusCode;
use axum::response::IntoResponse;
use axum::Json;
use chrono::NaiveDate;
use serde::{Deserialize, Serialize};
use serde_json::Value as JsonValue;
use uuid::Uuid;

use crate::jobs::repository::JobRepository;
use crate::jobs::types::{Job, JobType};
use crate::server::state::AppState;

/// Request to create a load job
#[derive(Debug, Deserialize)]
pub struct LoadRequest {
    /// Start date in YYYY-MM-DD format
    pub start_date: String,
    /// Number of days to load (1-365)
    pub days: i64,
    /// If true, execute synchronously and wait for completion
    /// If false or omitted, execute asynchronously and return job-id immediately
    #[serde(default)]
    pub sync: Option<bool>,
}

/// Response for successful sync load execution
#[derive(Debug, Serialize)]
pub struct LoadSyncResponse {
    pub job_id: Uuid,
    pub status: String,
    pub result: Option<JsonValue>,
}

/// Response for async load submission
#[derive(Debug, Serialize)]
pub struct LoadAsyncResponse {
    pub job_id: Uuid,
    pub status: String,
    pub poll_url: String,
}

/// Response for job status query
#[derive(Debug, Serialize)]
pub struct JobResponse {
    pub job_id: Uuid,
    pub job_type: String,
    pub status: String,
    pub payload: Option<JsonValue>,
    pub result: Option<JsonValue>,
    pub error: Option<JobErrorResponse>,
    pub created_at: String,
    pub updated_at: String,
    pub started_at: Option<String>,
    pub completed_at: Option<String>,
}

/// Error details for failed jobs
#[derive(Debug, Serialize)]
pub struct JobErrorResponse {
    pub code: String,
    pub message: String,
}

/// Error response body
#[derive(Debug, Serialize)]
pub struct ErrorResponse {
    pub error: String,
    pub message: String,
}

/// Request parameters for listing jobs
#[derive(Debug, Deserialize)]
pub struct ListJobsRequest {
    /// Filter by status (pending, in_process, complete, failed)
    pub status: Option<String>,
    /// Maximum number of jobs to return (default: 20, max: 100)
    #[serde(default = "default_limit")]
    pub limit: i64,
    /// Offset for pagination (default: 0)
    #[serde(default = "default_offset")]
    pub offset: i64,
}

fn default_limit() -> i64 { 20 }
fn default_offset() -> i64 { 0 }

/// Response for job listing
#[derive(Debug, Serialize)]
pub struct ListJobsResponse {
    pub jobs: Vec<JobResponse>,
    pub total: i64,
    pub limit: i64,
    pub offset: i64,
}

/// POST /api/v1/load - Create and execute a load job
///
/// In sync mode (sync=true): Blocks until completion, returns full job with result
/// In async mode (sync=false or omitted): Returns immediately with job-id for polling
pub async fn load_handler(
    State(state): State<AppState>,
    Json(request): Json<LoadRequest>,
) -> impl IntoResponse {
    // Validate days parameter (must be 1-365)
    if request.days < 1 || request.days > 365 {
        let error = ErrorResponse {
            error: "invalid_days".to_string(),
            message: format!("Days must be between 1 and 365, got {}", request.days),
        };
        return (StatusCode::BAD_REQUEST, Json(serde_json::json!(error))).into_response();
    }

    // Validate date format (YYYY-MM-DD)
    if NaiveDate::parse_from_str(&request.start_date, "%Y-%m-%d").is_err() {
        let error = ErrorResponse {
            error: "invalid_date".to_string(),
            message: format!(
                "Invalid date format: '{}', expected YYYY-MM-DD",
                request.start_date
            ),
        };
        return (StatusCode::BAD_REQUEST, Json(serde_json::json!(error))).into_response();
    }

    // Build payload JSON
    let payload = serde_json::json!({
        "start_date": request.start_date,
        "days": request.days,
    });

    let sync_mode = request.sync.unwrap_or(false);

    if sync_mode {
        // Synchronous execution: block until completion
        match state.executor().execute_sync(JobType::Load, payload).await {
            Ok(job) => {
                let response = LoadSyncResponse {
                    job_id: job.id,
                    status: job.status,
                    result: job.result,
                };
                (StatusCode::OK, Json(serde_json::json!(response))).into_response()
            }
            Err(e) => {
                tracing::error!("Sync load job failed: {}", e);
                let error = ErrorResponse {
                    error: "execution_failed".to_string(),
                    message: format!("{}", e),
                };
                (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!(error))).into_response()
            }
        }
    } else {
        // Asynchronous execution: return job-id immediately
        match state.executor().execute_async(JobType::Load, payload).await {
            Ok(job_id) => {
                let response = LoadAsyncResponse {
                    job_id,
                    status: "pending".to_string(),
                    poll_url: format!("/api/v1/jobs/{}", job_id),
                };
                (StatusCode::ACCEPTED, Json(serde_json::json!(response))).into_response()
            }
            Err(e) => {
                tracing::error!("Async load job submission failed: {}", e);
                let error = ErrorResponse {
                    error: "submission_failed".to_string(),
                    message: format!("{}", e),
                };
                (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!(error))).into_response()
            }
        }
    }
}

/// GET /api/v1/jobs/:id - Get job details and status
///
/// Returns full job information including:
/// - Job metadata (id, type, status, timestamps)
/// - Payload (input parameters)
/// - Result (output data, if complete)
/// - Error (error details, if failed)
pub async fn get_job_handler(
    State(state): State<AppState>,
    Path(job_id): Path<Uuid>,
) -> impl IntoResponse {
    let repository = JobRepository::new(state.get_pool());

    match repository.get_job(job_id).await {
        Ok(Some(job)) => {
            let response = build_job_response(job);
            (StatusCode::OK, Json(serde_json::json!(response))).into_response()
        }
        Ok(None) => {
            let error = ErrorResponse {
                error: "not_found".to_string(),
                message: format!("Job {} not found", job_id),
            };
            (StatusCode::NOT_FOUND, Json(serde_json::json!(error))).into_response()
        }
        Err(e) => {
            tracing::error!("Failed to get job {}: {}", job_id, e);
            let error = ErrorResponse {
                error: "query_failed".to_string(),
                message: format!("{}", e),
            };
            (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!(error))).into_response()
        }
    }
}

/// GET /api/v1/jobs - List recent jobs with pagination
///
/// Query parameters:
/// - status: Filter by status (optional)
/// - limit: Max jobs to return (default: 20, max: 100)
/// - offset: Pagination offset (default: 0)
pub async fn list_jobs_handler(
    State(state): State<AppState>,
    Query(params): Query<ListJobsRequest>,
) -> impl IntoResponse {
    let repository = JobRepository::new(state.get_pool());

    // Validate and cap limit
    let limit = params.limit.max(1).min(100);
    let offset = params.offset.max(0);

    // Parse status filter if provided
    let status_filter: Option<crate::jobs::types::JobStatus> = params.status.clone().and_then(|s| match s.as_str() {
        "pending" => Some(crate::jobs::types::JobStatus::Pending),
        "in_process" => Some(crate::jobs::types::JobStatus::InProcess),
        "complete" => Some(crate::jobs::types::JobStatus::Complete),
        "failed" => Some(crate::jobs::types::JobStatus::Failed),
        _ => None,
    });

    // If invalid status was provided, return error
    if params.status.is_some() && status_filter.is_none() {
        let error = ErrorResponse {
            error: "invalid_status".to_string(),
            message: format!(
                "Invalid status filter: '{}'. Valid values: pending, in_process, complete, failed",
                params.status.unwrap()
            ),
        };
        return (StatusCode::BAD_REQUEST, Json(serde_json::json!(error))).into_response();
    }

    // Build filters from single status (backward-compatible; T03 adds multi-value support)
    let filters = crate::jobs::repository::JobListFilters {
        status: status_filter.into_iter().collect(),
        ..Default::default()
    };

    // Get total count for pagination
    let total_result = repository.count_jobs(filters.clone()).await;

    match total_result {
        Ok(total) => {
            match repository.list_jobs(filters, limit, offset).await {
                Ok(jobs) => {
                    let responses: Vec<JobResponse> = jobs
                        .into_iter()
                        .map(build_job_response)
                        .collect();

                    let response = ListJobsResponse {
                        jobs: responses,
                        total,
                        limit,
                        offset,
                    };

                    (StatusCode::OK, Json(serde_json::json!(response))).into_response()
                }
                Err(e) => {
                    tracing::error!("Failed to list jobs: {}", e);
                    let error = ErrorResponse {
                        error: "query_failed".to_string(),
                        message: format!("Failed to retrieve jobs: {}", e),
                    };
                    (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!(error))).into_response()
                }
            }
        }
        Err(e) => {
            tracing::error!("Failed to count jobs: {}", e);
            let error = ErrorResponse {
                error: "query_failed".to_string(),
                message: format!("Failed to count jobs: {}", e),
            };
            (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!(error))).into_response()
        }
    }
}

/// Build a JobResponse from a Job entity
fn build_job_response(job: Job) -> JobResponse {
    let error_response = job.error.map(|err| {
        // Try to extract code and message from error JSON
        let code = err
            .get("code")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown_error")
            .to_string();
        let message = err
            .get("message")
            .and_then(|v| v.as_str())
            .unwrap_or("An unknown error occurred")
            .to_string();
        JobErrorResponse { code, message }
    });

    JobResponse {
        job_id: job.id,
        job_type: job.job_type,
        status: job.status,
        payload: job.payload,
        result: job.result,
        error: error_response,
        created_at: job.created_at.to_rfc3339(),
        updated_at: job.updated_at.to_rfc3339(),
        started_at: job.started_at.map(|t| t.to_rfc3339()),
        completed_at: job.completed_at.map(|t| t.to_rfc3339()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::jobs::types::{Job, JobType};

    #[test]
    fn test_load_request_deserialization() {
        let json = r#"{"start_date":"2024-01-01","days":7}"#;
        let req: LoadRequest = serde_json::from_str(json).unwrap();
        assert_eq!(req.start_date, "2024-01-01");
        assert_eq!(req.days, 7);
        assert_eq!(req.sync, None);
    }

    #[test]
    fn test_load_request_with_sync() {
        let json = r#"{"start_date":"2024-01-01","days":7,"sync":true}"#;
        let req: LoadRequest = serde_json::from_str(json).unwrap();
        assert_eq!(req.sync, Some(true));
    }

    #[test]
    fn test_load_request_with_explicit_async() {
        let json = r#"{"start_date":"2024-01-01","days":7,"sync":false}"#;
        let req: LoadRequest = serde_json::from_str(json).unwrap();
        assert_eq!(req.sync, Some(false));
    }

    #[test]
    fn test_load_sync_response_serialization() {
        let response = LoadSyncResponse {
            job_id: Uuid::nil(),
            status: "complete".to_string(),
            result: Some(serde_json::json!({"loaded": 7})),
        };
        let json = serde_json::to_string(&response).unwrap();
        assert!(json.contains("complete"));
        assert!(json.contains("loaded"));
    }

    #[test]
    fn test_load_async_response_serialization() {
        let response = LoadAsyncResponse {
            job_id: Uuid::nil(),
            status: "pending".to_string(),
            poll_url: "/api/v1/jobs/00000000-0000-0000-0000-000000000000".to_string(),
        };
        let json = serde_json::to_string(&response).unwrap();
        assert!(json.contains("pending"));
        assert!(json.contains("/api/v1/jobs/"));
    }

    #[test]
    fn test_job_response_building() {
        let job = Job::new(JobType::Load, serde_json::json!({"test": true}));
        let response = build_job_response(job);
        assert_eq!(response.job_type, "load");
        assert_eq!(response.status, "pending");
    }

    #[test]
    fn test_job_error_response_extraction() {
        let mut job = Job::new(JobType::Load, serde_json::json!({}));
        job.error = Some(serde_json::json!({
            "code": "validation_failed",
            "message": "Invalid date range"
        }));

        let response = build_job_response(job);
        assert!(response.error.is_some());
        let err = response.error.unwrap();
        assert_eq!(err.code, "validation_failed");
        assert_eq!(err.message, "Invalid date range");
    }

    #[test]
    fn test_error_response_serialization() {
        let error = ErrorResponse {
            error: "test_error".to_string(),
            message: "Something went wrong".to_string(),
        };
        let json = serde_json::to_string(&error).unwrap();
        assert!(json.contains("test_error"));
        assert!(json.contains("Something went wrong"));
    }

    #[test]
    fn test_list_jobs_request_deserialization() {
        // Test with all parameters
        let json = r#"{"status":"complete","limit":10,"offset":5}"#;
        let req: ListJobsRequest = serde_json::from_str(json).unwrap();
        assert_eq!(req.status, Some("complete".to_string()));
        assert_eq!(req.limit, 10);
        assert_eq!(req.offset, 5);
    }

    #[test]
    fn test_list_jobs_request_defaults() {
        // Test with empty JSON (should use defaults)
        let json = r#"{}"#;
        let req: ListJobsRequest = serde_json::from_str(json).unwrap();
        assert_eq!(req.status, None);
        assert_eq!(req.limit, 20);  // default_limit
        assert_eq!(req.offset, 0);   // default_offset
    }

    #[test]
    fn test_list_jobs_request_partial() {
        // Test with only status filter
        let json = r#"{"status":"pending"}"#;
        let req: ListJobsRequest = serde_json::from_str(json).unwrap();
        assert_eq!(req.status, Some("pending".to_string()));
        assert_eq!(req.limit, 20);  // default
        assert_eq!(req.offset, 0);   // default
    }

    #[test]
    fn test_list_jobs_response_serialization() {
        let job = Job::new(JobType::Load, serde_json::json!({"test": true}));
        let job_response = build_job_response(job);

        let response = ListJobsResponse {
            jobs: vec![job_response],
            total: 1,
            limit: 20,
            offset: 0,
        };

        let json = serde_json::to_string(&response).unwrap();
        assert!(json.contains("\"total\":1"));
        assert!(json.contains("\"limit\":20"));
        assert!(json.contains("\"offset\":0"));
        assert!(json.contains("\"jobs\""));
    }

    #[test]
    fn test_list_jobs_handler_response_format() {
        // This test verifies the response structure matches API-06 requirements
        let job = Job::new(
            JobType::Query,
            serde_json::json!({
                "query_name": "wedding",
                "start_date": "2024-06-01",
                "days": 30
            }),
        );

        let response = build_job_response(job);

        // Verify all API-06 required fields are present
        assert!(!response.job_id.to_string().is_empty());
        assert!(!response.job_type.is_empty());
        assert!(!response.status.is_empty());
        assert!(!response.created_at.is_empty());
        assert!(!response.updated_at.is_empty());
        // started_at and completed_at are optional
        // payload, result, error are optional

        // Serialize and verify JSON structure
        let json = serde_json::to_value(&response).unwrap();
        assert!(json.get("job_id").is_some());
        assert!(json.get("job_type").is_some());
        assert!(json.get("status").is_some());
        assert!(json.get("created_at").is_some());
        assert!(json.get("updated_at").is_some());
    }

    #[test]
    fn test_list_jobs_response_includes_pagination() {
        let job1 = Job::new(JobType::Load, serde_json::json!({"test": 1}));
        let job2 = Job::new(JobType::Query, serde_json::json!({"test": 2}));

        let response = ListJobsResponse {
            jobs: vec![build_job_response(job1), build_job_response(job2)],
            total: 2,
            limit: 20,
            offset: 0,
        };

        let json = serde_json::to_value(&response).unwrap();
        assert!(json.get("jobs").is_some());
        assert!(json.get("total").is_some());
        assert!(json.get("limit").is_some());
        assert!(json.get("offset").is_some());

        let jobs = json.get("jobs").unwrap().as_array().unwrap();
        assert_eq!(jobs.len(), 2);
    }

    #[test]
    fn test_job_response_with_optional_fields() {
        let mut job = Job::new(JobType::Load, serde_json::json!({"test": true}));

        // Set optional fields
        job.started_at = Some(chrono::Utc::now());
        job.completed_at = Some(chrono::Utc::now());
        job.result = Some(serde_json::json!({"loaded": 7}));

        let response = build_job_response(job);

        // Verify required fields
        assert!(!response.job_id.to_string().is_empty());
        assert_eq!(response.job_type, "load");
        assert_eq!(response.status, "pending");

        // Verify optional fields are present
        assert!(response.started_at.is_some());
        assert!(response.completed_at.is_some());
        assert!(response.result.is_some());
        assert!(response.error.is_none());
    }

    #[test]
    fn test_job_response_with_error() {
        let mut job = Job::new(JobType::Query, serde_json::json!({}));
        job.error = Some(serde_json::json!({
            "code": "validation_failed",
            "message": "Invalid query parameters"
        }));

        let response = build_job_response(job);

        assert!(response.error.is_some());
        let error = response.error.unwrap();
        assert_eq!(error.code, "validation_failed");
        assert_eq!(error.message, "Invalid query parameters");
    }
}

use crate::jobs::error::{JobError, JobResult};
use crate::jobs::types::{Job, JobStatus, JobType};
use chrono::{DateTime, Utc};
use serde_json::Value as JsonValue;
use sqlx::{Pool, Postgres, QueryBuilder};
use uuid::Uuid;

/// Parsed filter parameters for listing jobs.
/// Shared contract between the handler (which parses query strings) and the repository.
#[derive(Debug, Clone, Default)]
pub struct JobListFilters {
    pub status: Vec<JobStatus>,
    pub job_type: Vec<JobType>,
    pub created_after: Option<DateTime<Utc>>,
    pub created_before: Option<DateTime<Utc>>,
}

/// Repository for job CRUD operations and job queue claiming
#[derive(Debug, Clone)]
pub struct JobRepository {
    pool: Pool<Postgres>,
}

impl JobRepository {
    pub fn new(pool: Pool<Postgres>) -> Self {
        Self { pool }
    }

    /// Get reference to the connection pool
    pub fn pool(&self) -> &Pool<Postgres> {
        &self.pool
    }

    /// Create a new job in pending status
    pub async fn create_job(
        &self,
        job_type: JobType,
        payload: JsonValue,
    ) -> JobResult<Job> {
        let job = Job::new(job_type, payload);

        sqlx::query_as::<_, Job>(
            r#"
            INSERT INTO jobs (id, job_type, status, payload, created_at, updated_at)
            VALUES ($1, $2, $3, $4, $5, $6)
            RETURNING *
            "#
        )
        .bind(job.id)
        .bind(&job.job_type)
        .bind(&job.status)
        .bind(&job.payload)
        .bind(job.created_at)
        .bind(job.updated_at)
        .fetch_one(&self.pool)
        .await
        .map_err(JobError::from)
    }

    /// Get job by ID
    pub async fn get_job(&self, id: Uuid
    ) -> JobResult<Option<Job>> {
        sqlx::query_as::<_, Job>(
            "SELECT * FROM jobs WHERE id = $1"
        )
        .bind(id)
        .fetch_optional(&self.pool)
        .await
        .map_err(JobError::from)
    }

    /// Claim next pending job using FOR UPDATE SKIP LOCKED (race-free)
    /// Returns the claimed job or None if no jobs available
    pub async fn claim_next_job(
        &self,
        worker_id: &str,
    ) -> JobResult<Option<Job>> {
        let now = Utc::now();

        sqlx::query_as::<_, Job>(
            r#"
            UPDATE jobs 
            SET status = 'in_process', 
                started_at = $1, 
                updated_at = $1,
                worker_id = $2
            WHERE id = (
                SELECT id FROM jobs 
                WHERE status = 'pending' 
                ORDER BY created_at 
                FOR UPDATE SKIP LOCKED
                LIMIT 1
            )
            RETURNING *
            "#
        )
        .bind(now)
        .bind(worker_id)
        .fetch_optional(&self.pool)
        .await
        .map_err(JobError::from)
    }

    /// Update job status with validation
    pub async fn update_job_status(
        &self,
        id: Uuid,
        new_status: JobStatus,
        result: Option<JsonValue>,
        error: Option<JsonValue>,
    ) -> JobResult<Job> {
        // Get current job to validate transition
        let current = self.get_job(id).await?;
        let job = current.ok_or_else(|| JobError::NotFound(id.to_string()))?;

        let current_status = job.status_enum()
            .ok_or_else(|| JobError::Other(format!("Invalid status: {}", job.status)))?;

        if !current_status.can_transition_to(new_status) {
            return Err(JobError::InvalidStatusTransition(
                current_status.to_string(),
                new_status.to_string(),
            ));
        }

        let now = Utc::now();

        sqlx::query_as::<_, Job>(
            r#"
            UPDATE jobs 
            SET status = $1, 
                updated_at = $2,
                completed_at = CASE WHEN $1 IN ('complete', 'failed') THEN $2 ELSE completed_at END,
                result = COALESCE($3, result),
                error = COALESCE($4, error)
            WHERE id = $5
            RETURNING *
            "#
        )
        .bind(new_status.as_ref())
        .bind(now)
        .bind(result)
        .bind(error)
        .bind(id)
        .fetch_one(&self.pool)
        .await
        .map_err(JobError::from)
    }

    /// List jobs with dynamic filtering and pagination
    #[allow(unused_assignments)]
    pub async fn list_jobs(
        &self,
        filters: JobListFilters,
        limit: i64,
        offset: i64,
    ) -> JobResult<Vec<Job>> {
        let mut query = QueryBuilder::new("SELECT * FROM jobs");
        let mut has_where = false;

        if !filters.status.is_empty() {
            query.push(" WHERE status IN (");
            let mut separated = query.separated(", ");
            for s in &filters.status {
                separated.push_bind(s.as_ref());
            }
            query.push(")");
            has_where = true;
        }

        if !filters.job_type.is_empty() {
            if has_where {
                query.push(" AND job_type IN (");
            } else {
                query.push(" WHERE job_type IN (");
                has_where = true;
            }
            let mut separated = query.separated(", ");
            for jt in &filters.job_type {
                separated.push_bind(jt.as_ref());
            }
            query.push(")");
        }

        if let Some(after) = filters.created_after {
            if has_where {
                query.push(" AND created_at >= ");
            } else {
                query.push(" WHERE created_at >= ");
                has_where = true;
            }
            query.push_bind(after);
        }

        if let Some(before) = filters.created_before {
            if has_where {
                query.push(" AND created_at <= ");
            } else {
                query.push(" WHERE created_at <= ");
                has_where = true;
            }
            query.push_bind(before);
        }

        query.push(" ORDER BY created_at DESC LIMIT ");
        query.push_bind(limit);
        query.push(" OFFSET ");
        query.push_bind(offset);

        query.build_query_as::<Job>()
            .fetch_all(&self.pool)
            .await
            .map_err(JobError::from)
    }

    /// Count jobs with dynamic filtering
    #[allow(unused_assignments)]
    pub async fn count_jobs(&self, filters: JobListFilters) -> JobResult<i64> {
        let mut query = QueryBuilder::new("SELECT COUNT(*) FROM jobs");
        let mut has_where = false;

        if !filters.status.is_empty() {
            query.push(" WHERE status IN (");
            let mut separated = query.separated(", ");
            for s in &filters.status {
                separated.push_bind(s.as_ref());
            }
            query.push(")");
            has_where = true;
        }

        if !filters.job_type.is_empty() {
            if has_where {
                query.push(" AND job_type IN (");
            } else {
                query.push(" WHERE job_type IN (");
                has_where = true;
            }
            let mut separated = query.separated(", ");
            for jt in &filters.job_type {
                separated.push_bind(jt.as_ref());
            }
            query.push(")");
        }

        if let Some(after) = filters.created_after {
            if has_where {
                query.push(" AND created_at >= ");
            } else {
                query.push(" WHERE created_at >= ");
                has_where = true;
            }
            query.push_bind(after);
        }

        if let Some(before) = filters.created_before {
            if has_where {
                query.push(" AND created_at <= ");
            } else {
                query.push(" WHERE created_at <= ");
                has_where = true;
            }
            query.push_bind(before);
        }

        let count: (i64,) = query.build_query_as()
            .fetch_one(&self.pool)
            .await
            .map_err(JobError::from)?;

        Ok(count.0)
    }
}

/// Repository for tracking loaded date ranges
#[derive(Debug, Clone)]
pub struct LoadedDaysRepository {
    pool: Pool<Postgres>,
}

impl LoadedDaysRepository {
    pub fn new(pool: Pool<Postgres>) -> Self {
        Self { pool }
    }

    /// Mark a date as loaded with coverage information
    pub async fn mark_day_loaded(
        &self,
        date: chrono::NaiveDate,
        coverage_minutes: i16,
        job_id: Option<Uuid>,
    ) -> JobResult<()> {
        sqlx::query(
            r#"
            INSERT INTO loaded_days (date, coverage_minutes, loaded_at, job_id)
            VALUES ($1, $2, NOW(), $3)
            ON CONFLICT (date) DO UPDATE SET
                coverage_minutes = EXCLUDED.coverage_minutes,
                loaded_at = EXCLUDED.loaded_at,
                job_id = EXCLUDED.job_id
            "#
        )
        .bind(date)
        .bind(coverage_minutes)
        .bind(job_id)
        .execute(&self.pool)
        .await
        .map_err(JobError::from)?;

        Ok(())
    }

    /// Check if a date is already loaded
    pub async fn is_day_loaded(
        &self,
        date: chrono::NaiveDate,
    ) -> JobResult<bool> {
        let row: Option<(i64,)> = sqlx::query_as(
            "SELECT 1 FROM loaded_days WHERE date = $1 LIMIT 1"
        )
        .bind(date)
        .fetch_optional(&self.pool)
        .await
        .map_err(JobError::from)?;

        Ok(row.is_some())
    }

    /// Get dates in a range that are NOT loaded
    pub async fn get_missing_dates(
        &self,
        start: chrono::NaiveDate,
        days: i64,
    ) -> JobResult<Vec<chrono::NaiveDate>> {
        // Generate series of dates and find which aren't in loaded_days
        let rows: Vec<(chrono::NaiveDate,)> = sqlx::query_as(
            r#"
            SELECT gs::date as date
            FROM generate_series($1::date, $1::date + ($2 || ' days')::interval, '1 day'::interval) gs
            WHERE gs::date NOT IN (
                SELECT date FROM loaded_days 
                WHERE date BETWEEN $1 AND $1 + ($2 || ' days')::interval
            )
            ORDER BY gs::date
            "#
        )
        .bind(start)
        .bind(days)
        .fetch_all(&self.pool)
        .await
        .map_err(JobError::from)?;

        Ok(rows.into_iter().map(|r| r.0).collect())
    }

    /// Get loaded date range summary
    pub async fn get_loaded_range_summary(
        &self,
    ) -> JobResult<Option<(chrono::NaiveDate, chrono::NaiveDate, i64)>> {
        let row: Option<(chrono::NaiveDate, chrono::NaiveDate, i64)> = sqlx::query_as(
            "SELECT MIN(date), MAX(date), COUNT(*) FROM loaded_days"
        )
        .fetch_optional(&self.pool)
        .await
        .map_err(JobError::from)?;

        Ok(row)
    }
}

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use serde_json::Value as JsonValue;
use sqlx::FromRow;
use uuid::Uuid;

/// Job types supported by the system
#[derive(
    Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, strum_macros::Display,
    strum_macros::AsRefStr,
    strum_macros::EnumString,
)]
#[strum(serialize_all = "snake_case")]
#[serde(rename_all = "snake_case")]
pub enum JobType {
    Load,  // Load planetary data for date range
    Query, // Execute named query (wedding, project, travel)
}

/// Job status with state machine enforcement
/// Valid transitions: pending → in_process → (complete | failed)
#[derive(
    Debug,
    Clone,
    Copy,
    PartialEq,
    Eq,
    Serialize,
    Deserialize,
    strum_macros::Display,
    strum_macros::AsRefStr,
    strum_macros::EnumString,
)]
#[strum(serialize_all = "snake_case")]
#[serde(rename_all = "snake_case")]
pub enum JobStatus {
    Pending,
    InProcess,
    Complete,
    Failed,
}

impl JobStatus {
    /// Check if a status transition is valid
    pub fn can_transition_to(&self, new_status: JobStatus) -> bool {
        matches!(
            (self, new_status),
            (JobStatus::Pending, JobStatus::InProcess)
                | (JobStatus::InProcess, JobStatus::Complete)
                | (JobStatus::InProcess, JobStatus::Failed)
        )
    }
}

/// Job entity representing an async operation
#[derive(Debug, Clone, FromRow)]
pub struct Job {
    pub id: Uuid,
    pub job_type: String, // Stored as string in DB, parse to JobType
    pub status: String,   // Stored as string in DB, parse to JobStatus
    pub payload: Option<JsonValue>,
    pub result: Option<JsonValue>,
    pub error: Option<JsonValue>,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
    pub started_at: Option<DateTime<Utc>>,
    pub completed_at: Option<DateTime<Utc>>,
}

impl Job {
    /// Create a new job with pending status
    pub fn new(job_type: JobType, payload: JsonValue) -> Self {
        let now = Utc::now();
        Self {
            id: Uuid::new_v4(),
            job_type: job_type.to_string(),
            status: JobStatus::Pending.to_string(),
            payload: Some(payload),
            result: None,
            error: None,
            created_at: now,
            updated_at: now,
            started_at: None,
            completed_at: None,
        }
    }

    /// Parse job_type string to enum
    pub fn job_type_enum(&self) -> Option<JobType> {
        match self.job_type.as_str() {
            "load" => Some(JobType::Load),
            "query" => Some(JobType::Query),
            _ => None,
        }
    }

    /// Parse status string to enum
    pub fn status_enum(&self) -> Option<JobStatus> {
        match self.status.as_str() {
            "pending" => Some(JobStatus::Pending),
            "in_process" => Some(JobStatus::InProcess),
            "complete" => Some(JobStatus::Complete),
            "failed" => Some(JobStatus::Failed),
            _ => None,
        }
    }

    /// Get duration since job was started (if in progress)
    pub fn duration(&self) -> Option<chrono::Duration> {
        match (self.started_at, self.completed_at) {
            (Some(start), Some(end)) => Some(end - start),
            (Some(start), None) => Some(Utc::now() - start),
            _ => None,
        }
    }
}

